const rows = $input.all().map(function(i){ return i.json; });
const orders = new Map();
for (const r of rows) {
  const pid = r.pedido_id;
  if (!orders.has(pid)) {
    orders.set(pid, {
      pedido_id: pid,
      usuario_id: r.usuario_id,
      email: r.email,
      nombre: r.displayname || r.username || r.email,
      moneda: r.moneda || 'USD',
      total: Number(r.total),
      creado_el: String(r.creado_el || ''),
      puntos_previos: Number(r.puntos) || 0,
      compras_previas: Number(r.compras_previas) || 0,
      items: [],
      baja_stock: []
    });
  }
  const o = orders.get(pid);
  o.items.push({ nombre: r.nombre_producto, cantidad: Number(r.cantidad), precio: Number(r.precio) });
  if (Number(r.prod_stock) <= Number(r.prod_stock_min)) {
    o.baja_stock.push(r.prod_nombre + ' (quedan ' + r.prod_stock + ' uds)');
  }
}
function money(n, cur){ return (cur === 'USD' ? '$' : cur + ' ') + Number(n).toFixed(2); }
const out = [];
const running = new Map();
for (const o of orders.values()) {
  if (!running.has(o.usuario_id)) running.set(o.usuario_id, o.puntos_previos);
  const base = running.get(o.usuario_id);
  const ganados = Math.floor(o.total);
  const puntos_total = base + ganados;
  running.set(o.usuario_id, puntos_total);
  const nivel_key = puntos_total >= 600 ? 'platino' : puntos_total >= 300 ? 'oro' : puntos_total >= 100 ? 'plata' : 'nuevo';
  const nivel = nivel_key.charAt(0).toUpperCase() + nivel_key.slice(1);
  let cupon_pct = 0, cupon_tipo = '';
  if (o.total >= 150) { cupon_pct = 10; cupon_tipo = 'Compra de alto valor'; }
  else if (o.compras_previas === 0) { cupon_pct = 5; cupon_tipo = 'Cliente nuevo'; }
  const cupon_codigo = cupon_pct ? ('PV' + cupon_pct + '-' + String(o.pedido_id) + '-' + Math.random().toString(36).slice(2,6).toUpperCase()) : '';
  const admin_alert = (o.total >= 250 || o.baja_stock.length > 0);
  let filas = '';
  o.items.forEach(function(it){
    const line = it.precio * it.cantidad;
    filas += '<tr>'
      + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;color:#1f2937;font-weight:600;">' + it.nombre + '</td>'
      + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;text-align:center;color:#6b7280;">' + it.cantidad + '</td>'
      + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;text-align:right;color:#6b7280;">' + money(it.precio, o.moneda) + '</td>'
      + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;text-align:right;color:#111827;font-weight:600;">' + money(line, o.moneda) + '</td>'
      + '</tr>';
  });
  if (!filas) filas = '<tr><td colspan="4" style="padding:12px;text-align:center;color:#6b7280;">Sin items</td></tr>';
  const fidelidad = '<div style="margin-top:18px;padding:14px 16px;border-radius:10px;background:#111827;color:#e5e7eb;">'
    + '<div style="font-size:12px;color:#fbbf24;font-weight:700;letter-spacing:1px;text-transform:uppercase;">Programa de fidelidad</div>'
    + '<div style="margin-top:6px;font-size:14px;">Ganaste <b style="color:#fbbf24;">+' + ganados + ' puntos</b> con esta compra.</div>'
    + '<div style="margin-top:2px;font-size:14px;">Ahora tienes <b>' + puntos_total + ' puntos</b> - nivel <b style="color:#fbbf24;">' + nivel + '</b>.</div>'
    + '</div>';
  let cupon = '';
  if (cupon_codigo) {
    cupon = '<div style="margin-top:14px;padding:16px;border-radius:10px;border:2px dashed #fbbf24;background:#fffbeb;text-align:center;">'
      + '<div style="font-size:12px;color:#92400e;font-weight:700;text-transform:uppercase;letter-spacing:1px;">Cupon ' + cupon_tipo + '</div>'
      + '<div style="margin-top:6px;font-size:26px;font-weight:800;color:#111827;">' + cupon_pct + '% OFF</div>'
      + '<div style="margin-top:4px;font-size:14px;color:#374151;">Usa el codigo</div>'
      + '<div style="margin-top:3px;font-size:18px;font-weight:800;letter-spacing:2px;color:#b45309;">' + cupon_codigo + '</div>'
      + '<div style="margin-top:6px;font-size:12px;color:#6b7280;">Valido por 30 dias en tu proxima compra.</div>'
      + '</div>';
  }
  const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="margin:0;padding:0;background:#f3f4f6;font-family:Helvetica,Arial,sans-serif;">'
    + '<div style="max-width:600px;margin:24px auto;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb;">'
    + '<div style="background:linear-gradient(135deg,#111827,#1f2937);padding:24px 28px;">'
    + '<div style="font-size:22px;font-weight:800;letter-spacing:1px;color:#fbbf24;">PIXELVAULT</div>'
    + '<div style="font-size:12px;color:#9ca3af;margin-top:4px;letter-spacing:2px;text-transform:uppercase;">Tu pedido confirmado</div>'
    + '</div>'
    + '<div style="padding:24px 28px;">'
    + '<p style="margin:0 0 6px;font-size:16px;color:#111827;">Hola <b>' + o.nombre + '</b>,</p>'
    + '<p style="margin:0 0 16px;font-size:14px;color:#6b7280;">Gracias por tu compra. Aqui esta tu factura.</p>'
    + '<table style="width:100%;border-collapse:collapse;font-size:14px;">'
    + '<tr style="background:#f9fafb;"><th style="padding:9px 12px;text-align:left;color:#6b7280;font-size:11px;text-transform:uppercase;">Producto</th><th style="padding:9px 12px;text-align:center;color:#6b7280;font-size:11px;text-transform:uppercase;">Cant.</th><th style="padding:9px 12px;text-align:right;color:#6b7280;font-size:11px;text-transform:uppercase;">Precio</th><th style="padding:9px 12px;text-align:right;color:#6b7280;font-size:11px;text-transform:uppercase;">Subtotal</th></tr>'
    + filas
    + '</table>'
    + '<div style="text-align:right;margin-top:14px;font-size:18px;color:#111827;"><b>Total: ' + money(o.total, o.moneda) + '</b></div>'
    + fidelidad
    + cupon
    + '<p style="margin:20px 0 0;font-size:12px;color:#9ca3af;">Pedido #' + o.pedido_id + ' - ' + o.creado_el + '</p>'
    + '</div>'
    + '<div style="padding:14px 28px;background:#f9fafb;font-size:11px;color:#9ca3af;text-align:center;">PIXELVAULT - Correo automatico, no responder.</div>'
    + '</div></body></html>';
  let admin_html = '<h3>Automatizacion PIXELVAULT - Pedido #' + o.pedido_id + '</h3>'
    + '<p>Cliente: ' + o.email + '<br>Total: ' + money(o.total, o.moneda) + '<br>Nivel: ' + nivel + '</p>';
  if (o.baja_stock.length) admin_html += '<p><b>Stock bajo tras la compra:</b> ' + o.baja_stock.join(', ') + '</p>';
  if (o.total >= 250) admin_html += '<p><b>Pedido de alto valor.</b></p>';
  out.push({ json: {
    pedido_id: o.pedido_id,
    usuario_id: o.usuario_id,
    email: o.email,
    subject: 'Tu factura PIXELVAULT - Pedido #' + o.pedido_id,
    email_html: html,
    puntos_total: puntos_total,
    nivel: nivel,
    nivel_key: nivel_key,
    puntos_ganados: ganados,
    cupon_codigo: cupon_codigo,
    cupon_pct: cupon_pct,
    cupon_tipo: cupon_tipo,
    admin_flag: admin_alert ? 'si' : '',
    admin_subject: 'PIXELVAULT - Alerta pedido #' + o.pedido_id,
    admin_html: admin_html,
    resumen: 'Factura enviada; +' + ganados + ' pts; nivel ' + nivel + (cupon_codigo ? ('; cupon ' + cupon_codigo) : '')
  }});
}
return out;

const items = $input.all().map(function(i){ return i.json; });
const out = [];
for (const r of items) {
  const nombre = r.displayname || r.username || r.email;
  const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="margin:0;padding:0;background:#f3f4f6;font-family:Helvetica,Arial,sans-serif;">'
    + '<div style="max-width:600px;margin:24px auto;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb;">'
    + '<div style="background:linear-gradient(135deg,#111827,#1f2937);padding:24px 28px;">'
    + '<div style="font-size:22px;font-weight:800;letter-spacing:1px;color:#fbbf24;">PIXELVAULT</div>'
    + '<div style="font-size:12px;color:#9ca3af;margin-top:4px;letter-spacing:2px;text-transform:uppercase;">Como te fue con tu compra</div>'
    + '</div>'
    + '<div style="padding:24px 28px;">'
    + '<p style="margin:0 0 8px;font-size:16px;color:#111827;">Hola <b>' + nombre + '</b>,</p>'
    + '<p style="margin:0 0 16px;font-size:14px;color:#6b7280;">Hace poco compraste en PIXELVAULT (pedido #' + r.pedido_id + '). Nos encantaria saber que tal te parecio. Tu opinion nos ayuda a mejorar.</p>'
    + '<p style="margin:0 0 20px;"><a href="http://localhost/pixelV/views/products.html" style="display:inline-block;background:#fbbf24;color:#111827;font-weight:700;text-decoration:none;padding:12px 22px;border-radius:8px;">Dejanos tu resena</a></p>'
    + '<p style="margin:0;font-size:12px;color:#9ca3af;">Gracias por ser parte de PIXELVAULT.</p>'
    + '</div>'
    + '<div style="padding:14px 28px;background:#f9fafb;font-size:11px;color:#9ca3af;text-align:center;">PIXELVAULT - Correo automatico, no responder.</div>'
    + '</div></body></html>';
  out.push({ json: Object.assign({}, r, { subject: 'Como te fue con tu pedido PIXELVAULT #' + r.pedido_id, review_html: html }) });
}
return out;
